const CINEMA_DATA = [{"id":"perfect-days","title":"퍼펙트 데이즈","year":2023,"type":"영화","director":"빔 벤더스","actors":["야쿠쇼 코지"],"genres":["드라마"],"audiences":["혼자","지친 날","생각하고 싶은 날"],"themes":["삶의 태도","일상","변화","회복"],"moods":["지침","무기력","혼란","차분함"],"outcomes":["위로","정돈","회복","생각"],"intensity":1,"why":"변화를 멈출 수 없는 세계에서 붙잡을 수 있는 것은 결국 ‘삶에 대한 태도’라는 시선으로 오래 남은 작품.","quote":"반복되는 삶에도 모든 것은 변한다… 유일하게 변화를 잠시나마 붙잡을 수 있는 것이 있다면 그것은 오직 나의 ‘삶에 대한 태도’일 것이다.","connections":["치히로 상","리틀 포레스트","소라닌"],"colors":["#535b4d","#1d2520"],"fullComment":"반복되는 삶에도 모든 것은 변한다. 흘러가는 시간, 사람 사이의 관계, 일, 자연, 마음 등등 이 세상에 변하지 않 는 것은 없다. 그리고 그 어떤 인간도 그러한 변화를 멈추지 못한다. 만약 유일하게 변화를 잠시나마 붙잡을 수 있는 것이 있다면 그것은 오직 나의 ‘삶에 대한 태도’ 일 것이다. 그래서 그것을 붙잡기 위한 절실한 노력이 우리 를 고통으로, 그리고 순간의 아름다움으로 이끈다","archiveIds":["m-054"],"critiqueTags":["신선함과 자기복제"],"tone":"대체로 비판"},{"id":"little-forest","title":"리틀 포레스트","year":2018,"type":"영화","director":"임순례","actors":["김태리","류준열","진기주"],"genres":["드라마"],"audiences":["혼자","가족","지친 날"],"themes":["삶의 태도","자연","회복","성장"],"moods":["지침","무기력","답답함"],"outcomes":["위로","회복","여유"],"intensity":1,"why":"삶의 경험이 깊어질수록 비로소 보이는 것들을 천천히 발견하게 해주는 영화.","quote":"삶의 경험이 깊어질 수록 보이는 것들, 그리고 알게 되는 것들.","connections":["리틀 포레스트: 사계절","퍼펙트 데이즈"],"colors":["#776c45","#26352a"],"fullComment":"삶의 경험이 깊어질 수록 보이는 것들, 그리고 알게 되는 것들, ‘아주 심기’ 를 하고나면 비로소 발견하는 것과 그 토록 찾던 무언가와 마주하여 짓는 웃음","archiveIds":["m-195"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"chihiro","title":"치히로 상","year":2023,"type":"영화","director":"이마이즈미 리키야","actors":["아리무라 카스미"],"genres":["드라마"],"audiences":["혼자","연인","지친 날"],"themes":["삶의 태도","관계","고통","자기수용"],"moods":["외로움","지침","혼란"],"outcomes":["위로","회복","다정함"],"intensity":1,"why":"삶의 속도를 조절하고, 타인의 고통을 알아보고, ‘지금 그대로의 너’를 받아들이는 이야기.","quote":"우리는 때로 멈춰서서 쉬어야 할 때를 맞이한다… ‘지금 그대로의 네가 좋아’.","connections":["퍼펙트 데이즈","소라닌"],"colors":["#715d5a","#24242e"],"fullComment":"시간과 인생은 계속해서 흘러가지만 우리는 때로 멈춰서서 쉬어야할 때를 맞이한다 즉, 우리 스스로 ‘인생걸음’의 속도를 조절하고 조정해야하는 순간을 겪는다. 그러므로 삶은 그토록 다양할진대 왜 사람들은 삶의 모습이 정해져있다는 듯이 행동해야만 제대로 된 삶을 살고 있다고 생각하는 것일까? 인생은 참으로 아이러니하다 모든 사람은 한번이라도 누군가와는 관계를 맺고 살 수 밖에 없는데 고통을 겪은 사람만이 타인의 고통을 알아줄\n수 있고 그것을 안아줄수도 있다 또 사람들이 타인에게 바라는 것은 ‘이거 좋다’ 하면 ‘그거 좋네’, ‘그렇지?’라고 물으면 ‘그렇다’라고 말해주는 것 인데 우리는 각자의 이유로 그 쉬운 바람을 들어주지 않는다 우리가 각자 어떤 별에서 왔듯, 지금 어디에 있든, 앞으로 어디를 가게 되든 “지금 그대로의 네가 좋아”","archiveIds":["m-063"],"critiqueTags":[],"tone":"대체로 호평"},{"id":"solanin","title":"소라닌","year":2010,"type":"영화","director":"미키 타카히로","actors":["미야자키 아오이"],"genres":["드라마","음악"],"audiences":["혼자","친구","청춘"],"themes":["삶의 태도","청춘","꿈","관계"],"moods":["무기력","답답함","상실"],"outcomes":["위로","용기","회복"],"intensity":2,"why":"세상을 바꾸지 못해도 소중한 사람들과의 삶을 지켜나가는 것만으로 충분할 수 있다는 믿음.","quote":"세상을 바꾸지 못하더라도 나와 내 가족과 내 주변의 소중한 사람과의 삶을 함께 지켜나가는 것만으로도 충분하다.","connections":["퍼펙트 데이즈","카메라를 멈추면 안 돼!"],"colors":["#65706f","#1f2729"],"fullComment":"누구나 어렸을 땐 멋진 사람으로 자라나서 세상을 바꾸리라 꿈을 꿔 하지만 자라면서 세상이 그렇게 녹록치 않다는 것을 알게 되지 그러나 이에 좌절한다거나 슬퍼하진 않을거야 대신 알게 되었거든 세상을 바꾸지 못하더라도 나와 내 가족과 내 주변의 소중한 사람과의 삶을 함께 지켜나가는 것만으로도 충분하 다는 것을","archiveIds":["m-391"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"whiplash","title":"위플래쉬","year":2014,"type":"영화","director":"데이미언 셔젤","actors":["마일스 텔러","J.K. 시몬스"],"genres":["드라마","음악"],"audiences":["혼자","친구","강렬한 밤"],"themes":["극기","욕망","성취","예술"],"moods":["분노","무기력","답답함","들뜸"],"outcomes":["각성","몰입","카타르시스"],"intensity":5,"why":"궁극의 경지에 도달하기 위해 괴물을 만들 수 있는 자와 기꺼이 괴물이 될 수 있는 자의 결투.","quote":"감독이 이 영화를 본 관객에게 바라는 반응은 오로지 경이로움 그 하나다. 아니면 fuck up.","connections":["라라랜드","바빌론","블루 자이언트"],"colors":["#7a4a27","#1a1311"],"fullComment":"2023.10.03 추가 : 이리저리 핑계되고 이것저것 재며 정치질 난무하는 세상을 향해 욕설을 날리며 모든 것을\n해체해버리는 분노의 질주\n2021.04.02 추가 : 궁극의 경지에 도달하기 위해서라면 괴물을 만들 수 있는 자와 기꺼이 괴물도 될 수 있는 자\n사이의 극기의 결투\n첫 관람 후 : 감독이 이 영화를 본 관객에게 바라는 반응은 오로지 경이로움 그 하나다 아니면 fuck up. 이거나...","archiveIds":["m-321"],"critiqueTags":[],"tone":"대체로 호평"},{"id":"ford-v-ferrari","title":"포드 V 페라리","year":2019,"type":"영화","director":"제임스 맨골드","actors":["맷 데이먼","크리스찬 베일"],"genres":["드라마","스포츠"],"audiences":["친구","혼자","동료"],"themes":["열정","성취","시스템","선택"],"moods":["답답함","무기력","분노"],"outcomes":["각성","용기","카타르시스"],"intensity":4,"why":"승리를 위한 게임보다 승산을 향한 질주를 멈추지 않는 사람들을 향한 경의.","quote":"가슴이 뜨거운 사람(들)을 위한 사회는 없다.","connections":["F1 더 무비","머니볼","위플래쉬"],"colors":["#6f2830","#1e1d23"],"fullComment":"가슴이 뜨거운 사람(들)을 위한 사회는 없다. 승리를 위한 게임보다 승산을 향한 질주를 멈추지 않는 아니, 결코 멈출 생각도 없고 절대 멈추지 않을, 가슴 안에 뜨거운 심장이 뛰고 있는 사람들을 향한 경의","archiveIds":["m-167"],"critiqueTags":[],"tone":"대체로 비판"},{"id":"inglourious","title":"바스터즈: 거친 녀석들","year":2009,"type":"영화","director":"쿠엔틴 타란티노","actors":["브래드 피트","크리스토프 왈츠"],"genres":["전쟁","블랙코미디","스릴러"],"audiences":["혼자","친구","강렬한 밤"],"themes":["폭력과 역사","복수","인간성","장르적 쾌감"],"moods":["분노","답답함","들뜸"],"outcomes":["카타르시스","몰입","전율"],"intensity":5,"why":"서스펜스, 밀도 높은 캐릭터, 대체역사의 장르적 쾌감이 한꺼번에 작동하는 타란티노의 정점 중 하나.","quote":"서스펜스의 경지란 이런 것.","connections":["헤이트풀 8","장고: 분노의 추적자","13인의 자객"],"colors":["#8b2b22","#221410"],"fullComment":"서스펜스의 경지란 이런 것. 뿐만 아니라 밀도 높은 캐릭터와 흠잡을 곳 없는 비유와 대비가 어우러지는 장면 구 성, 대체역사물이 선사하는 장르적 쾌감까지 이루 말할 데가 없다. 일순간의 동정심으로 죽은 쇼샤나에게 경의 를. 처벌받아야 할 존재를 모두 불태워버리고 그녀는 응당 인간의 품위를 지키며 우리의 곁을 떠났다. 피로 점철 된 인류 역사에서 그러한 사람들은 언제 어디에서나 있었을 것이다.","archiveIds":["m-403"],"critiqueTags":["캐릭터","장르 이해","연출과 미장센"],"tone":"대체로 비판"},{"id":"the-batman","title":"더 배트맨","year":2022,"type":"영화","director":"맷 리브스","actors":["로버트 패틴슨","조이 크라비츠"],"genres":["범죄","스릴러","히어로"],"audiences":["혼자","친구","영화관"],"themes":["성장","분노","책임","희망"],"moods":["분노","혼란","답답함"],"outcomes":["몰입","생각","각성"],"intensity":4,"why":"분노의 복수에서 사람들이 따르는 그림자로 성장하는 배트맨을 통해 분노의 방향과 책임을 묻는 작품.","quote":"분노의 복수에서 사람들이 따르는 그림자로.","connections":["세븐","블레이드 러너","다크나이트","혹성탈출: 반격의 서막"],"colors":["#5d1a1c","#121317"],"fullComment":"한줄평: 분노의 복수에서 사람들이 따르는 그림자로\n상세후기 사실 새로운 배트맨 시리즈가 시작된다고 했을 때 저의 첫 반응은 덤덤했습니다. 하지만 새로운 프랜차이즈를 이 끄는 감독이 '맷 리브스'라는 것을 알게 된 후 그를 좋아하는 관객 중 하나였던 저는 호들갑까지는 아니었어도 영 화가 개봉하기를 기다리고 있었습니다. 그리고 우리나라에는 3월에 개봉을 했고 마침 오늘 시간이 나서 영화를 감상하고 왔습니다. 먼저 제가 영화를 감상하면서 가장 인상깊었던 점은 리들리 스콧 감독의 <블레이드 러너>에서의 도시를 연상시 키는 고담시의 모습과 시종일관 어두운 분위기 속에서 데이빗 핀처 감독의 <세븐>에서와 같이 사건이 발생할 때 마다 추적추적 비가 내리는 모습의 연출, 또 이러한 도시 안에서 스스로를 '그림자'라고 말하는 '배트맨'이 리들러 의 수수께끼를 풀면서 진실을 쫓는 과정에서 커져가는 '분노'의 크기에 따라 관객의 눈과 귀에 어떻게 보면 과한 인상을 남기려는 듯한 연출(특히 작중 '펭귄'을 쫓으며 그의 속에서 분출되는 분노의 거대한 포효를 대변하는 듯 한 배트카의 엔진소리')이었습니다. 즉, 본 작품은 '연출'에 상당히 신경을 많이 썼기 때문에 영화관에서 관람했 을 때 더 즐겁게 볼 수 있는 작품에는 분명합니다. 그런데 사실상 3시간에 가까운 런닝타임은 대중성 면에서는 도전에 가깝습니다. 물론 엄밀히 보자면 <더 배트맨 >은 2시간 안팎으로도 충분히 보여줄 수 있는 이야기였다고 생각해요(유사한 런닝타임을 가진 <반지의 제왕> 과 비교해볼 때 <반지의 제왕>에서 풀어야 할 이야기만큼 많았다고 보기는 어렵죠..) 하지만 전 개인적으로 맷 리브스 감독이 3시간의 런닝타임을 고수한 것이 올바른 결정이었다고 생각하고 그 결정 또한 이해합니다. 본 영 화가 크리스토퍼 놀란 감독의 <다크나이트>에서의 주제의식을 공유하면서도 맷 리브스 감독만의 새로운 스타 일을 추구하고 있었기 때문에 앞으로 이런 스타일의 <배트맨> 시리즈를 보게 될 거야 라고 관객에게 선언하는 것과 같았다고 생각했습니다. 무엇보다 배트맨의 성장을 담고 있기 때문에 관객이 그의 변화를 아주 세밀하게 관 찰할 수 있도록 말이죠 자. 방금 말씀드렸다시피 본 영화의 서사는 '배트맨'의 성장을 담고 있습니다. 분노의 '복수'에서 사람들이 따르는 '그림자', 즉 고담시의 '다크나이트'로 성장하는 배트맨의 이야기를 담고 있죠. 그리고 우리가 너무 잘 알다시피 '배트맨'은 '브루스 웨인'이며 그가 가면을 쓴 것은 그의 부모가 살해당한 것이 계기가 되었죠. <더 배트맨>은 그 러한 '브루스 웨인'이 '배트맨'으로 활동한지 2년이 된 시점에서 이야기가 시작됩니다. 그리고 이야기의 중심에는 부패의 온상인 고담시에 대해 분노로 가득찬 인물들의 대립과 갈등이 있습니다 \"분노한 사람은 자신의 분노를 보지 못하고 늘 남의 분노만 본다. 분노에 사로잡힌 사람은 자신의 악행을 더 이 상 인지하지 못할 뿐만 아니라 모든 악한 것을 상대방에게 투사한다. 또 분노의 맹목성이 심해지면 애초의 대상 을 시야에서 놓쳐버리고 분노가 일어난 데에 대해 전혀 의심도 하지 않은 채 아무런 원인도 제공하지 않은 ‘우연 한 대상’에게로 자신의 격한 분노를 급작스럽게 옮겨 놓을 수 있다. 분노는 대상을 가리지 않고 맹목적으로 일어 난다\" (르네 지라르) 영화 중반부까지 '배트맨'이나 '리들러'나 '분노'에 가득차있는 것은 똑같습니다. 그렇기에 둘 다 자신이 결정한 목 적을 달성하기 위해 '맹목적'입니다. 배트맨은 스스로를 그림자로 칭하며 '공포'를 도구삼아 고담시의 '질서'를 바 로 잡으려고 하고 리들러의 경우도 '공포'를 도구삼지만 궁긍적으로는 고담시를 '파괴'하려하죠. 이처럼 서로 목 적은 달라도 '공포'를 도구로 삼는다는 점에서 리들러와 배트맨의 분노가 가지는 성격은 유사합니다. 그래서 리 들러는 <다크나이트>에서 조커가 이야기했듯이 배트맨이 자신을 완성시킨다고 이야기하기도 하죠. 그러나 배 트맨을 좋아하는(?) 조커와 달리 리들러의 분노는 배트맨에게도 향해있습니다. 결정적인 이유는 리들러는 배트 맨이 부모의 죽음으로 '고아'가 된 것에 괴로워하는 것을 '기만'으로 보고있기 때문입니다. 리들러가 아는, 그리고 스스로 경험한 '고아'는 한 방에서 30명씩 지내며 언제 죽어나갈지 모르는 그런 모습입니다. 그러나 배트맨, 브 루스 웨인은 웨인 가의 유산을 상속받아 큰 성에서 지내며 고담시를 내려다보면서 징징되고 있는 '아이'에 불과 한 것이죠. 그래서 리들러는 영화가 진행되는 내내 분노의 방향을 고담시의 '파괴'로 맹목적으로 밀어붙입니다. 물론 그 이 면에는 치밀하게 세워진 '계획'이 있었지만 그 목적은 오직 고담시의 파괴와 브루스 웨인의 죽음에만 매몰되어있 습니다. 그러나 '캣 우먼'과의 만남을 통해 스스로를 돌아보는 계기를 마주한 배트맨의 분노의 방향은 점점 다른\n쪽으로 바뀌어갑니다. 배트맨이 '팔코네'로부터 받아들이기 어려운 사실을 알게 되고 또 다시 '알프레도'와의 대 화를 통해 '진실'을 알게 된 후 배트맨은 자신에게 아직까지 소중한 자신의 사람들을 잃어버리게 될지 모른다는 '두려움'이 남아있었다는 것을 자각합니다. 그리고 이를 자각한 배트맨은 부모의 갑작스런 죽음에서 받게 된 상 실감과 큰 상처를 극복하고자하는 의지를 보이면서 끝내 성장하게 됩니다 (우스갯소리로 이 성장은 리들러의 상위호환이라 할 수 있는 '조커'와의 만남을 위한 것이 아니었을까..)\n아마 이 이야기를 통해 맷 리브스 감독은 오늘날 급격하게 변화하는 사회에서 '악'이 수면 위로 들어날 때마다 사 람들이 느끼는 분노의 방향을 어디로 향해야하는 가를 묻고 있다고 생각합니다. 그리고 그에 대한 답 또한 관객 에게 분명하게 전달하고 있습니다. 아무리 '악'이 활개치는 사회에서도 분명히 옳은 일을 하려는 '소수'는 있고 아 무리 좋은 사람이라도 '실수' 할 수 있다는 사실을 이해하려는 노력과 또 실수를 한 사람도 그 실수를 인정하고 책임지려는 '행동' 등이 중요하다고 이야기하고 있죠. 결국 중요한 것은 더 좋아질 수 있고 나아질 수 있다고 하 는 '믿음'이라는 것이죠. 배트맨은 고담시의 시민들을 구하기 위해 자신을 희생하는 것에도 망설임이 없습니다. 캣 우먼이 같이 떠나자고 해도 고담시를 선택하는 완전히 우리가 알고 있는 배트맨의 모습으로 거듭나죠. 네. 우리가 <다크나이트>에서 보았던 그 고결한 배트맨의 모습입니다 배트맨은 처음에는 스스로를 '그림자'로 칭하며 공포를 도구로 질서를 잡고자하였습니다. 그러나 배트맨은 이제 불을 붙인 신호탄으로 어둠에 빠진 고담시민들의 앞길을 밝혀주는 '그림자'가 되었습니다. 마지막으로 영화에서 는 이를 아주 멋지게 연출하는데 저는 단연코 <더 배트맨>에서 가장 인상깊었던 장면이라고 말씀드리고 싶습니 다.\n→ 관련: 더 배트맨을 보고 왔습니다","archiveIds":["m-106"],"critiqueTags":["연출과 미장센","장르 이해","캐릭터","주제의식"],"tone":"호평"},{"id":"arrival","title":"컨택트","year":2016,"type":"영화","director":"드니 빌뇌브","actors":["에이미 아담스","제레미 레너"],"genres":["SF","드라마"],"audiences":["혼자","연인","생각하고 싶은 날"],"themes":["선택과 책임","소통","사랑","자유의지"],"moods":["혼란","외로움","차분함"],"outcomes":["생각","여운","위로"],"intensity":2,"why":"소통과 불통의 벽, 자유의지와 선택의 아름다움을 동시에 밀어붙이는 SF.","quote":"인간이 ‘자유의지’로 ‘선택’하는 아름다움에 대한 이야기를 강렬하게 전달하고 있다.","connections":["듄","인터스텔라","뉴스 오브 더 월드"],"colors":["#6b7777","#1a2225"],"fullComment":"‘소통’과 ‘불통’ 사이의 벽을 허무는 것은 상대에게 필요한 나의 것을 먼저 나누는 마음으로부터 시작된다. 이와 함께 감독은 인간이 ‘자유의지’로 ‘선택’하는 아름다움에 대한 이야기를 강렬하게 전달하고 있다","archiveIds":["m-261"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"dune","title":"듄","year":2021,"type":"영화","director":"드니 빌뇌브","actors":["티모시 샬라메","레베카 퍼거슨"],"genres":["SF","모험"],"audiences":["혼자","친구","영화관"],"themes":["선택과 책임","운명","성장","권력"],"moods":["들뜸","혼란"],"outcomes":["몰입","생각","전율"],"intensity":4,"why":"운명을 따르거나 거스르는 대신, 주어진 것에 어떻게 응답할 것인가를 묻는 작품.","quote":"운명엔 순응하는 것도 개척하는 것도 아니다. 응답하는 것뿐이다.","connections":["듄: 파트2","컨택트","그린 나이트"],"colors":["#8a6a43","#2f261d"],"fullComment":"운명엔 순응하는 것도 개척하는 것도 아니다. 응답하는 것뿐이다","archiveIds":["m-120"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"la-la-land","title":"라라랜드","year":2016,"type":"영화","director":"데이미언 셔젤","actors":["라이언 고슬링","엠마 스톤"],"genres":["로맨스","음악","드라마"],"audiences":["연인","혼자","친구"],"themes":["선택과 책임","사랑","꿈","시간"],"moods":["설렘","외로움","그리움"],"outcomes":["여운","감정","생각"],"intensity":3,"why":"꿈과 사랑, 성공과 실패가 동시에 어긋나는 삶을 결국 순간의 선택으로 바라보게 만드는 영화.","quote":"우리의 삶은 순간순간의 판단과 선택으로 만들어지는 것.","connections":["위플래쉬","바빌론","비긴 어게인"],"colors":["#47306d","#1a1530"],"fullComment":"꿈과 사랑, 만남과 이별, 기쁨과 슬픔, 영광과 상처, 성공과 실패는 언제나 우리의 삶 속에서 함께하고 또 어긋난 다. 그래도 시간은 멈추지 않고 흘러만가기에 (영원히 멈춰있고 싶은 순간에도 미아를 떠나보내고 피아노를 연주해 야하는 세바스찬의 모습처럼) 우리의 삶은 순간순간의 판단과 선택으로 만들어지는 것...","archiveIds":["m-265"],"critiqueTags":[],"tone":"대체로 비판"},{"id":"babylon","title":"바빌론","year":2022,"type":"영화","director":"데이미언 셔젤","actors":["브래드 피트","마고 로비"],"genres":["드라마","코미디"],"audiences":["혼자","친구","강렬한 밤"],"themes":["예술","기억","욕망","영화사"],"moods":["들뜸","그리움","혼란"],"outcomes":["전율","여운","생각"],"intensity":5,"why":"한 시대의 빛과 그림자, 살아남기 위해 미쳐야 했던 사람들, 영화가 남기는 흔적을 한꺼번에 바라보는 작품.","quote":"우리 인생 또한 언젠가 무로 돌아가고 사람들의 기억에서도 사라지지만 흔적은 어딘가에 남아 후대에 의해 다시 기억된다.","connections":["라라랜드","위플래쉬","거미집"],"colors":["#8a5d2f","#2e1716"],"fullComment":"한 시대의 빛과 그림자, 그 속에서 살아남기위해, 또 살아가기위해 처절하게 몸부림쳐야했던, 달콤한 꿈을 이루 기 위해 미쳐야만했던, 인간 군상을 그려낸 데이미언 셔젤 감독이 보여준 할리우드 영화가 남긴 전쟁유산. 감독 은 우리 인생 또한 언젠가 무(無)로 돌아가고 사람들의 기억에서도 사라지지만 흔적은 어딘가에 남아 후대에 의 해 다시 기억되고 그렇게 영원할 것이라고 허무한 인생의 의미에 대해 관객에게 묻는다.\n→ 관련: 브래드 피트","archiveIds":["m-091"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"mother?","title":"어느 가족","year":2018,"type":"영화","director":"고레에다 히로카즈","actors":["릴리 프랭키","안도 사쿠라"],"genres":["드라마"],"audiences":["가족","혼자","생각하고 싶은 날"],"themes":["관계","가족","사회","사랑"],"moods":["외로움","상실","차분함"],"outcomes":["생각","위로","여운"],"intensity":2,"why":"‘가족’이라는 이름보다 서로 온기가 필요했던 ‘그들’을 바라보며 관계의 본질을 질문하는 영화.","quote":"이 영화는 ‘가족’에 관한 이야기가 아니다. ‘그들’에 대한 이야기다.","connections":["바닷마을 다이어리","세 번째 살인"],"colors":["#6d5c4f","#252220"],"fullComment":"이 영화는 ‘가족’에 관한 이야기가 아니다. ‘그들’에 대한 이야기다. 사회의 사각지대에 있고 서로 온기가 필요했 고 사랑을 찾고자 했던 ‘그들’의 이야기다. 어김없이 ‘관계’의 본질에 대해 깊이 질문을 던지는 고레에다 히로카즈 감독에게 감사하다","archiveIds":["m-197"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"grand-budapest","title":"그랜드 부다페스트 호텔","year":2014,"type":"영화","director":"웨스 앤더슨","actors":["랄프 파인즈","토니 레볼로리"],"genres":["코미디","드라마"],"audiences":["연인","가족","친구"],"themes":["이야기","기억","관계","미학"],"moods":["설렘","심심함","차분함"],"outcomes":["즐거움","미감","여운"],"intensity":2,"why":"완벽한 이야기꾼이라는 한 문장으로 정리될 만큼, 스타일과 이야기의 균형이 매력적인 작품.","quote":"이 감독은 완벽한 이야기꾼이다.","connections":["프렌치 디스패치","애스터로이드 시티","문라이즈 킹덤"],"colors":["#a16b75","#49323b"],"fullComment":"이 감독은 완벽한 이야기꾼이다.","archiveIds":["m-335"],"critiqueTags":[],"tone":"대체로 호평"},{"id":"french-dispatch","title":"프렌치 디스패치","year":2021,"type":"영화","director":"웨스 앤더슨","actors":["빌 머레이","틸다 스윈튼"],"genres":["코미디","드라마"],"audiences":["혼자","연인","예술 좋아하는 날"],"themes":["삶의 태도","예술","기억","사랑"],"moods":["차분함","그리움"],"outcomes":["여운","미감","생각"],"intensity":2,"why":"끔찍한 세계 속에서도 우리가 끝내 기억하고 기록하고 싶은 것은 ‘삶에 대한 사랑’이라는 영화.","quote":"결국 그들이, 그리고 우리가 기억하고자하는 것은 ‘삶에 대한 사랑’이다.","connections":["애스터로이드 시티","그랜드 부다페스트 호텔"],"colors":["#62605a","#22211f"],"fullComment":"이 세계에 우리의 삶이 있고 삶을 기억하고 기록하는 사람이 있고 또 이 기억과 기록을 남기고 알리는 사람이 있 다. 그런 세계 속에서 온갖 끔찍한 일이 일어나고 있지만 결국 그들이, 그리고 우리가 기억하고자하는 것은 '삶에 대한 사랑'이다.","archiveIds":["m-119"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"parasite","title":"기생충","year":2019,"type":"영화","director":"봉준호","actors":["송강호","조여정","최우식"],"genres":["드라마","스릴러","블랙코미디"],"audiences":["친구","연인","생각하고 싶은 날"],"themes":["계급","욕망","사회","우화"],"moods":["답답함","혼란"],"outcomes":["생각","몰입","카타르시스"],"intensity":4,"why":"웃픈 사회비판 영화가 알레고리 가득한 우화로 승화된 작품.","quote":"웃픈 사회비판 영화에서 알레고리 가득한 우화로 작품세계가 승화하였다.","connections":["옥자","설국열차","미키 17"],"colors":["#5d6357","#20231e"],"fullComment":"웃픈 사회비판 영화에서 알레고리 가득한 우화로 작품세계가 승화하였다","archiveIds":["m-162"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"okja","title":"옥자","year":2017,"type":"영화","director":"봉준호","actors":["안서현","틸다 스윈튼","제이크 질렌할"],"genres":["드라마","모험","블랙코미디"],"audiences":["친구","가족","생각하고 싶은 날"],"themes":["욕망","자본주의","생명","우화"],"moods":["분노","답답함"],"outcomes":["생각","카타르시스"],"intensity":3,"why":"단순한 이야기 안에 풍부한 담론과 유머, 해학을 밀도 있게 쌓아올린 봉준호의 개인적 최고작 중 하나.","quote":"이토록 완벽한 블랙코미디. 극도로 단순한 이야기 속에 담긴 풍부한 담론들.","connections":["기생충","설국열차","미키 17"],"colors":["#466a5d","#1d2c25"],"fullComment":"이토록 완벽한 블랙코미디 극도로 단순한 이야기 속에 담긴 풍부한 담론들 그러면서도 결코 멈추지 않는 유머감각과 그만의 뼈 있는 해학 그의 전 작품 들인 <지리멸렬> <플란다스의 개> <살인의 추억> <괴물> <마더> <설국열차> 의 각양각색 색깔 들이 모두 스며들어있고 그가 봤을 모든 작품들의 느낌이 그만의 색깔로 변형되어 그의 최고의 작품이 탄생했다. 마스터피스 라고 까진 하진 않을 것이다. 그저 다음 작품이 고대될 뿐.","archiveIds":["m-243"],"critiqueTags":["장르 이해","각색과 원작"],"tone":"호평"},{"id":"poor-things","title":"가여운 것들","year":2023,"type":"영화","director":"요르고스 란티모스","actors":["엠마 스톤","마크 러팔로"],"genres":["판타지","드라마","블랙코미디"],"audiences":["혼자","연인","도전적인 밤"],"themes":["욕망","성장","정체성","사회"],"moods":["심심함","들뜸","혼란"],"outcomes":["생각","자극","미감"],"intensity":4,"why":"프랑켄슈타인을 멋지게 재가공하며 인간의 탐구심과 욕망, 정체성, 사회적 위선을 동시에 조소하는 영화.","quote":"이렇게 멋지게 <프랑켄슈타인>을 재가공한 요르고스 란티모스 감독에게 찬사를!!","connections":["카인즈 오브 카인드니스","킬링 디어","프랑켄슈타인"],"colors":["#744d76","#2c1f31"],"fullComment":"이렇게 멋지게 <프랑켄슈타인>을 재가공한 요르고스 란티모스 감독에게 찬사를!! 고전영화의 탈을 쓴 연극을 보다가, 탐구심과 생물학적 욕망을 구분못하는 어리석은 어른을 보다가, 잔혹한 인류 의 역사를 보다가, 던져진 존재인 인간이 정체성을 찾아가는 모습을 보다가 마침내, 근원으로 돌아와 외면만 어 른일뿐 동물에 지나지 않는 인간에게 조소를 마음껏 던지며 poor things","archiveIds":["m-061"],"critiqueTags":[],"tone":"호평"},{"id":"the-power-of-the-dog","title":"파워 오브 도그","year":2021,"type":"영화","director":"제인 캠피온","actors":["베네딕트 컴버배치","키어스틴 던스트"],"genres":["드라마","서부"],"audiences":["혼자","생각하고 싶은 날"],"themes":["욕망","소유","관계","강박"],"moods":["답답함","혼란"],"outcomes":["생각","여운"],"intensity":3,"why":"소유와 집착, 강박을 파고들며 대화하지 못하는 인간들의 숨막히는 관계를 보여준다.","quote":"이 작품에서 등장하는 인물들은 그 누구도 대화를 하지 않는다. 오직 자기 이야기만 할 뿐이고 나의 감정을 발산할 뿐이다.","connections":["원 배틀 애프터 어나더","카인즈 오브 카인드니스"],"colors":["#755c3b","#2f2a21"],"fullComment":"소유와 집착, 그리고 강박증을 집요하게 파고들다. 이 작품에서 등장하는 인물들은 그 누구도 대화를 하지 않는 다. 오직 자기 이야기만 할 뿐이고 나의 감정을 발산할 뿐이다. 그래서 영화가 진행되는 내내 숨이 턱턱 막힌다. 그런데 이러한 숨막힘에서 벗어나는 순간이 있다. 필이 피터에게 자신을 필이라고 부르라고 한 그날부터다. 그러 나 그 이전에 또 다른 숨막힘을 불러올 사건이 있었다. 필 만의 장소를 피터가 발견했던 날 그날부터 피터는 토끼 를 잡을 덫을 놓는다\n→ 관련: 키어스틴 던스트","archiveIds":["m-112"],"critiqueTags":["캐릭터"],"tone":"혼합/유보"},{"id":"mad-max?","title":"미션 임파서블: 폴아웃","year":2018,"type":"영화","director":"크리스토퍼 맥쿼리","actors":["톰 크루즈","레베카 퍼거슨"],"genres":["액션","스릴러"],"audiences":["친구","연인","영화관"],"themes":["장르적 쾌감","책임","선택"],"moods":["심심함","답답함","들뜸"],"outcomes":["몰입","카타르시스","즐거움"],"intensity":5,"why":"프랜차이즈의 익숙함을 최고 수준의 실행력으로 밀어붙이는 영화적 쾌감.","quote":"무엇을 더 바랄까. 이 프랜차이즈는 언제나 평소와 같은데.","connections":["미션 임파서블: 로그네이션","탑건: 매버릭"],"colors":["#454f58","#171a1e"],"fullComment":"무엇을 더 바랄까 이 프랜차이즈는 언제나 평소와 같은데","archiveIds":["m-196"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"top-gun-maverick","title":"탑건: 매버릭","year":2022,"type":"영화","director":"조셉 코신스키","actors":["톰 크루즈","마일스 텔러"],"genres":["액션","드라마"],"audiences":["가족","친구","영화관"],"themes":["선택과 책임","성장","기억","장르적 쾌감"],"moods":["무기력","들뜸","답답함"],"outcomes":["각성","전율","즐거움"],"intensity":5,"why":"쉬운 선택이 아니라도 행동으로 보여주는 매버릭이라는 인물을 통해 선택과 책임을 밀어붙이는 블록버스터.","quote":"Not Easy Choice... But Maverick is Shows Us.","connections":["탑건","미션 임파서블: 폴아웃","F1 더 무비"],"colors":["#36566f","#171e25"],"fullComment":"Not Easy Choice... But Maverick is Shows Us\n→ 관련: '매버릭'은 그냥 보여준다고!","archiveIds":["m-104"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"spiderverse","title":"스파이더맨: 뉴 유니버스","year":2018,"type":"영화","director":"밥 퍼시케티 외","actors":["샤메익 무어"],"genres":["애니메이션","히어로","액션"],"audiences":["아이와","가족","친구","연인"],"themes":["성장","다양성","예술","영웅"],"moods":["무기력","심심함","들뜸"],"outcomes":["즐거움","각성","미감"],"intensity":4,"why":"영상예술의 재료를 과감하게 섞고도 완성도 높은 새로운 문법을 만들어낸 작품. 별 다섯의 강한 신호.","quote":"YNWA!","connections":["스파이더맨: 어크로스 더 유니버스","더 퍼스트 슬램덩크"],"colors":["#572b71","#162940"],"fullComment":"YNWA!","archiveIds":["m-186"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"first-slam-dunk","title":"더 퍼스트 슬램덩크","year":2022,"type":"영화","director":"이노우에 다케히코","actors":["송태섭","강백호"],"genres":["애니메이션","스포츠","드라마"],"audiences":["가족","친구","아이와"],"themes":["성장","마음","스포츠","기억"],"moods":["무기력","그리움","들뜸"],"outcomes":["전율","감동","용기"],"intensity":4,"why":"원작 팬과 비팬 모두에게 작동하는 스포츠 애니메이션이자, 결국 ‘전하고자 하는 마음’에 관한 작품.","quote":"전하고자하는 마음. 전해진 마음.","connections":["블루 자이언트","스파이더맨: 뉴 유니버스"],"colors":["#b54834","#2b1714"],"fullComment":"원작의 팬들이라면 제대로 된 슬램덩크 극장판 애니메이션을 볼 수 있다는 것만으로도 만족스러울거고 원작을 보지 않은 사람들도 최고의 퀄리티로 만들어진 스포츠 애니메이션을 감상할 수 있는 기회가 될 것이다(시사회 감상 후)\n1회차: 시사회 (자막)\n2회차: 개봉 첫 날 첫회차 (자막)\n3회차: 더빙\n까지 본 후 더 전하고 싶은 말 “전하고자하는 마음. 전해진 마음“\n→ 관련: The Fisrt Slam Dunk","archiveIds":["m-092"],"critiqueTags":["각색과 원작","주제의식"],"tone":"호평"},{"id":"sing","title":"씽","year":2016,"type":"영화","director":"가스 제닝스","actors":["매튜 맥커너히","리즈 위더스푼"],"genres":["애니메이션","음악","코미디"],"audiences":["아이와","가족","친구"],"themes":["꿈","음악","용기","성장"],"moods":["무기력","심심함"],"outcomes":["즐거움","감동","용기"],"intensity":2,"why":"뻔한 이야기가 진한 감동을 주는 모범적인 가족용 음악 애니메이션.","quote":"뻔한 이야기가 찐한 감동을 주는 모범적인 작품.","connections":["미라클 벨리에","블루 자이언트"],"colors":["#79506e","#263b55"],"fullComment":"2016년 영화관 서른번째 관람 영화 <씽>.\n왜 난 이 영화를 보는 동안 주성치 영화가 생각이 났을까? 뻔한 이야기가 찐한 감동을 주는 모범적인 작품","archiveIds":["m-266"],"critiqueTags":[],"tone":"혼합/유보"},{"id":"moonrise","title":"문라이즈 킹덤","year":2012,"type":"영화","director":"웨스 앤더슨","actors":["자레드 길먼","카라 헤이워드"],"genres":["코미디","드라마","로맨스"],"audiences":["연인","가족","아이와"],"themes":["사랑","성장","어른","관계"],"moods":["설렘","외로움","심심함"],"outcomes":["즐거움","다정함","생각"],"intensity":1,"why":"아이들의 사랑은 즐겁지만 그들에게는 너무도 진지하다. 어른이라면 어떤 어른으로 존재하는지 생각하게 한다.","quote":"아이들의 사랑이야기가 너무나도 즐겁다. 그러나 당사자들에겐 너무도 진지한 것.","connections":["개들의 섬","그랜드 부다페스트 호텔"],"colors":["#a18951","#42554c"],"fullComment":"아이들의 사랑이야기가 너무나도 즐겁다. 그러나 당사자들에겐 너무도 진지한 것. 어른이라면 아이들에게 어떤 어른으로 존재하고 있는지 생각하게 된다.","archiveIds":["m-374"],"critiqueTags":[],"tone":"대체로 호평"},{"id":"dark","title":"다크 시즌 1–3","year":2017,"type":"시리즈","director":"바란 보 오다르","actors":["루이스 호프만"],"genres":["SF","미스터리","드라마"],"audiences":["혼자","연인","정주행"],"themes":["욕망","운명","선택과 책임","현재"],"moods":["혼란","몰입하고 싶음","답답함"],"outcomes":["생각","몰입","여운"],"intensity":4,"why":"세 시즌을 관통해 욕망과 오만, 바꿀 수 없는 것, 불완전함을 받아들이고 현재를 사랑하라는 방향으로 읽은 시리즈.","quote":"결국엔 우리 인간이 ‘불완전’하다는 것을 받아들이고 ‘현재’를 사랑하라는 주제를 던지며 이야기의 대장정은 끝이 난다.","connections":["컨택트","메시아","블랙 미러"],"colors":["#40514f","#111a1d"],"fullComment":"“일어난 일은 일어난 것이다” 를 인정할 수 없는 자기 욕망의 굴레에서 결코 벗어나지 못하는 우리 인간들의 모 습들이 상징적으로 그려진다\n\n자신의 욕망에서 자유로워지지 않는 한 벗어날 수 없는 운명은 계속 반복될지니...인류의 어리석은 행위의 반복 은 역사로 구성된다\n덧붙임: 대부분의 명작이 그렇듯 이 작품 또한 배경음악의 역할이 절반이상...\n\n결코 바꿀 수 없는 것을 받아들이지 못하고 바꾸려고 하는 인간(들)의 ‘욕망’에 관하여 자신의 욕망으로 뒤틀린 ‘운명’을 스스로의 ‘의지’로 바로잡을 수 있다고 믿는 인간(들)의 ‘오만함’에 대하여 결국엔 우리 인간이 ‘불완전’하다는 것을 받아들이고 ‘현재’를 사랑하라는 주제를 던지며 이야기의 대장정은 끝 이 난다 다만 이 이야기는 끝이 났지만 이 세상은 여전히 인간의 ‘욕망’과 ‘오만함’으로 가득차있을 것이다 역설적이지만 그럼에도 나의 ‘욕망’과 ‘오만함’은 내 세상은 그렇게 만들지 않겠다고 속삭인다 “시작이 있는 곳에 끝이 있고 끝이 있는 곳에 시작이 있다”","archiveIds":["s-055","s-049","s-042"],"critiqueTags":["신선함과 자기복제","연출과 미장센","주제의식"],"tone":"시즌별 평가"},{"id":"last-of-us","title":"더 라스트 오브 어스 시즌 1","year":2023,"type":"시리즈","director":"크레이그 메이진 외","actors":["페드로 파스칼","벨라 램지"],"genres":["드라마","아포칼립스"],"audiences":["혼자","연인","정주행"],"themes":["선택과 책임","사랑","미래","윤리"],"moods":["혼란","상실","답답함"],"outcomes":["생각","감정","몰입"],"intensity":4,"why":"종말이 다가와야 선명해지는 선택과 책임의 무게를 게임의 주제의식과 함께 성공적으로 옮긴 시리즈.","quote":"만약 우리의 미래를 희생하여 현재를 살릴 수 있다면 우리는 선택의 여지없이 미래를 희생시키는 선택을 해야할까?","connections":["더 웨일","킹덤","지금 우리 학교는"],"colors":["#4f563f","#20251c"],"fullComment":"막다른 길, 즉 종말이 다가와야만 느껴지는 선택과 책임의 무거운 무게... 그리고 성인의 부끄러움은 무엇을 의미 하는가? 만약 우리의 미래를 희생하여 현재를 살릴 수 있다면 우리는 선택의 여지없이 미래를 희생시키는 선택 을 해야할까? 그럼 그 책임은 누구의 몫인가? 훌륭한 연출과 좋은 영상의 리듬과 스토리 호흡. 배우들의 연기력이 빛을 발하며 게임이 갖고 있던 주제의식을 드라마로 멋지게 전환하였다","archiveIds":["s-019"],"critiqueTags":["연출과 미장센","주제의식"],"tone":"호평"},{"id":"chernobyl","title":"체르노빌","year":2019,"type":"시리즈","director":"요한 렌크","actors":["자레드 해리스","스텔란 스카스가드"],"genres":["드라마","역사"],"audiences":["혼자","생각하고 싶은 날","정주행"],"themes":["진실","시스템","책임","폭력과 역사"],"moods":["답답함","분노","혼란"],"outcomes":["생각","각성","몰입"],"intensity":4,"why":"거짓과 기만으로 진실의 무게를 버티려는 시스템과, 결국 그 무게를 견뎌야 하는 개인을 바라보는 작품.","quote":"결국 진실의 무게를 견뎌내야하는 것은 우리 개인의 몫이다.","connections":["제로 데이","시빌 워: 분열의 시대"],"colors":["#565941","#1a1d18"],"fullComment":"“아무도 자기 일들이 되리라고는 생각안해” 인간의 사회(시스템)는 진실의 무게를 거짓과 기만, 환상과 은폐로 견뎌보려하지만 결국 진실의 무게를 견뎌내 야하는 것은 우리 개인의 몫이다","archiveIds":["s-050"],"critiqueTags":[],"tone":"혼합/유보"}];
